package com.company.platform.administration.infrastructure;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class TenantSecurityFilter extends OncePerRequestFilter{protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var a=SecurityContextHolder.getContext().getAuthentication();if(a instanceof JwtAuthenticationToken jwt&&a.isAuthenticated()){String claim=jwt.getToken().getClaimAsString("tenant_id");if(claim==null)claim=jwt.getToken().getClaimAsString("tenantId");String header=req.getHeader("X-Tenant-Id");boolean platform=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_PLATFORM_ADMIN")||x.getAuthority().equals("PLATFORM_ADMIN"));if(header!=null&&(claim==null||!header.equals(claim))){res.sendError(403,"tenant context does not match token");return;}if(claim==null&&!platform){res.sendError(403,"tenant_id claim required");return;}if(claim!=null)try{java.util.UUID.fromString(claim);}catch(IllegalArgumentException e){res.sendError(403,"invalid tenant claim");return;}}chain.doFilter(req,res);}}
